options.css:
.french-b2b .french-b2b-header button .fa-chevron-down,
.french-b2b .french-b2b-header button .fa-chevron-up {
	margin-left: 2px;
}

.french-b2b .french-b2b-details {
	clear: both;
	padding-bottom: 10px;
	border-bottom-right-radius: 4px;
	display: none;
	animation: growDown 300ms ease-in-out forwards;
	background-color: #ffffff88;
	white-space: normal;
}

.french-b2b .french-b2b-details h5 a:link,
.french-b2b .french-b2b-details h5 a:hover {
	font: normal 14px 'Roboto Bold';
}

.french-b2b .french-b2b-details li {
	list-style-type: disc;
	margin-left: 30px;
	font: normal 12px 'Roboto';
}

.french-b2b-header::after {
	content: "";
	display: block;
	clear: both;
}

.bd-callout-info .french-b2b-details h5 a:link {
	color: #0082c0;
}

.bd-callout-info .french-b2b-details h5 a:hover {
	color: #005b86;
}

.bd-callout-warning .french-b2b-details h5 a:link {
	color: #ff8700;
}

.bd-callout-warning .french-b2b-details h5 a:hover {
	color: #cc6c00;
}

.bd-callout-danger .french-b2b-details h5 a:link {
	color: #e42518;
}

.bd-callout-FieldManager {
	padding: 0;
}

.bd-callout-FieldManager .secondColBody {
	padding: 0 !important;
}

.bd-callout {
	border-left: 4px solid;
	border-radius: 4px;
}

.bd-callout:not(:first-child) {
	margin-top: 10px;
}

.bd-callout::after {
	content: "";
	display: block;
	clear: both;
}

.bd-callout .button-callout {
	border: 1px;
	border-style: solid;
	box-sizing: border-box;
	border-radius: 4px;
	padding: 4px;
	margin: 6px;
	float: right;
	cursor: pointer;
	font: normal 16px 'Roboto Bold';
}

.bd-callout .button-callout-danger {
	background-color: #E42518;
	border-color: #E42518;
	color: #fce9e7;
}

.bd-callout .button-callout-warning {
	background-color: #ff8700;
	border-color: #ff8700;
	color: #fff3e5;
}

.bd-callout .button-callout-info {
	background-color: #0082c0;
	border-color: #0082c0;
	color: #e5f2f9;
}

.bd-callout h4 {
	float: left;
	line-height: 15px;
	padding: 4px;
	margin: 6px;
	font: normal 16px 'Roboto Bold';
	white-space: normal;
}

.bd-callout h5 {
	line-height: 15px;
	padding: 4px;
	margin: 6px;
	font: normal 14px 'Roboto Bold';
	white-space: normal;
}

.bd-callout h6 {
	line-height: 15px;
	padding: 4px;
	margin: 6px;
	font: normal 12px 'Roboto Bold';
	white-space: normal;
}

.bd-callout.bd-callout-info {
	border-left-color: #0082c0;
	background-color: #e5f2f9;
}

.bd-callout.bd-callout-info h4 {
	color: #0082c0;
}

.bd-callout.bd-callout-warning {
	border-left-color: #ff8700;
	background-color: #fff3e5;
}

.bd-callout.bd-callout-warning h4 {
	color: #ff8700;
}

.bd-callout.bd-callout-danger {
	border-left-color: #E42518;
	background-color: #fce9e7;
}

.bd-callout.bd-callout-danger h4 {
	color: #E42518;
}

.marginLeftAndRight {
	margin-right: -10px;
}

